// In-memory virtual font and ICC profile cache for PDFKit in serverless environments
import fs from "fs";
import path from "path";
import zlib from "zlib";

const GZ_PAYLOAD = "";
let fontCache = null;

function getFontCache() {
  if (!fontCache) {
    const jsonStr = zlib.gunzipSync(Buffer.from(GZ_PAYLOAD, "base64")).toString("utf8");
    fontCache = JSON.parse(jsonStr);
  }
  return fontCache;
}

let isPatched = false;
export function patchPdfkitFonts() {
  if (isPatched) return;
  isPatched = true;

  const origReadFileSync = fs.readFileSync;
  fs.readFileSync = function (filePath, options) {
    try {
      return origReadFileSync.call(fs, filePath, options);
    } catch (err) {
      if (err && err.code === "ENOENT" && typeof filePath === "string") {
        const base = path.basename(filePath);
        const cache = getFontCache();
        if (cache && cache[base]) {
          const buf = Buffer.from(cache[base], "base64");
          if (options === "utf8" || (typeof options === "object" && options && options.encoding === "utf8")) {
            return buf.toString("utf8");
          }
          return buf;
        }
      }
      throw err;
    }
  };
}

patchPdfkitFonts();
export default patchPdfkitFonts;
